import { 
  AppBar, Toolbar, Typography, Button, Box, IconButton, 
  Menu, MenuItem, Avatar, Divider, Badge, Switch, 
  styled, alpha, useTheme, Tooltip 
} from '@mui/material';
import { Link } from 'react-router-dom';
import { useState, useEffect, useRef } from 'react';
import { motion, useAnimation, AnimatePresence } from 'framer-motion';
import {
  Menu as MenuIcon,
  AccountCircle,
  Notifications,
  Brightness4,
  Brightness7,
  Search,
  KeyboardArrowUp
} from '@mui/icons-material';

// Glass morphism app bar
const GlassAppBar = styled(AppBar)(({ theme }) => ({
  background: `linear-gradient(
    135deg,
    ${alpha(theme.palette.primary.main, 0.95)} 0%,
    ${alpha(theme.palette.primary.dark, 0.95)} 100%
  )`,
  backdropFilter: 'blur(12px)',
  boxShadow: theme.shadows[10],
  borderBottom: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
  transition: 'all 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
}));

// Animated nav buttons
const NavButton = styled(Button)(({ theme }) => ({
  position: 'relative',
  margin: theme.spacing(0, 1),
  fontWeight: 600,
  letterSpacing: '0.8px',
  padding: theme.spacing(1, 2),
  borderRadius: theme.shape.borderRadius,
  overflow: 'hidden',
  '&::before': {
    content: '""',
    position: 'absolute',
    bottom: 0,
    left: 0,
    width: '100%',
    height: '2px',
    background: theme.palette.secondary.main,
    transform: 'scaleX(0)',
    transformOrigin: 'right',
    transition: 'transform 0.5s cubic-bezier(0.22, 1, 0.36, 1)',
  },
  '&:hover::before': {
    transform: 'scaleX(1)',
    transformOrigin: 'left',
  },
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: `0 4px 12px ${alpha(theme.palette.secondary.main, 0.2)}`,
  }
}));

const Navbar = ({ darkMode, toggleDarkMode }) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [scrolled, setScrolled] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const searchRef = useRef(null);
  const controls = useAnimation();
  const theme = useTheme();

  // Scroll handler
  useEffect(() => {
    const handleScroll = () => {
      const isScrolled = window.scrollY > 10;
      if (isScrolled !== scrolled) {
        setScrolled(isScrolled);
        controls.start(isScrolled ? 'scrolled' : 'normal');
      }
    };

    const debouncedScroll = debounce(handleScroll, 50);
    window.addEventListener('scroll', debouncedScroll);
    return () => window.removeEventListener('scroll', debouncedScroll);
  }, [scrolled, controls]);

  // Click outside search handler
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) {
        setSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleProfileMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const toggleSearch = () => {
    setSearchOpen(!searchOpen);
  };

  // Animation variants
  const variants = {
    scrolled: {
      height: '60px',
      backdropFilter: 'blur(20px)',
      boxShadow: theme.shadows[16],
    },
    normal: {
      height: '80px',
      backdropFilter: 'blur(12px)',
      boxShadow: theme.shadows[10],
    },
  };

  return (
    <>
      <motion.div
        animate={controls}
        initial="normal"
        variants={variants}
        style={{
          position: 'fixed',
          width: '100%',
          zIndex: theme.zIndex.appBar,
        }}
      >
        <GlassAppBar>
          <Toolbar sx={{ height: '100%' }}>
            {/* Mobile menu button */}
            <IconButton
              size="large"
              edge="start"
              color="inherit"
              aria-label="menu"
              sx={{ mr: 2, display: { xs: 'flex', md: 'none' } }}
              onClick={() => setAnchorEl(document.getElementById('mobile-menu-anchor'))}
            >
              <MenuIcon />
            </IconButton>

            {/* Logo/Brand */}
            <motion.div
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              style={{ display: 'flex', alignItems: 'center' }}
            >
              <Typography
                variant="h6"
                noWrap
                component={Link}
                to="/"
                sx={{
                  mr: 2,
                  fontWeight: 800,
                  letterSpacing: '.15rem',
                  color: 'inherit',
                  textDecoration: 'none',
                  display: 'flex',
                  alignItems: 'center',
                }}
              >
                
                
                FinTrack
              </Typography>
            </motion.div>

            {/* Search - desktop */}
            <AnimatePresence>
              {searchOpen && (
                <motion.div
                  initial={{ opacity: 0, width: 0 }}
                  animate={{ opacity: 1, width: '300px' }}
                  exit={{ opacity: 0, width: 0 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 30 }}
                  style={{ overflow: 'hidden' }}
                >
                  <div ref={searchRef} style={{
                    position: 'relative',
                    borderRadius: theme.shape.borderRadius * 2,
                    backgroundColor: alpha(theme.palette.common.white, 0.15),
                    marginRight: theme.spacing(2),
                    width: '100%',
                    transition: 'all 0.3s ease',
                  }}>
                    <div style={{
                      padding: theme.spacing(0, 2),
                      height: '100%',
                      position: 'absolute',
                      pointerEvents: 'none',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}>
                      <Search />
                    </div>
                    <input
                      placeholder="Search…"
                      style={{
                        color: 'inherit',
                        padding: theme.spacing(1, 1, 1, 0),
                        paddingLeft: `calc(1em + ${theme.spacing(4)})`,
                        width: '100%',
                        background: 'transparent',
                        border: 'none',
                        outline: 'none',
                        fontSize: '0.875rem',
                        fontWeight: 500,
                      }}
                      autoFocus
                    />
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <Box sx={{ flexGrow: 1 }} />

            {/* Desktop navigation */}
            <Box sx={{ display: { xs: 'none', md: 'flex' }, alignItems: 'center' }}>
              <Tooltip title="Search" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  onClick={toggleSearch}
                  sx={{ mr: 1 }}
                >
                  <Search />
                </IconButton>
              </Tooltip>

              <NavButton color="inherit" component={Link} to="/">
                Dashboard
              </NavButton>
              <NavButton color="inherit" component={Link} to="/stock">
                Stock
              </NavButton>
              <NavButton color="inherit" component={Link} to="/finance">
                Finance
              </NavButton>
              <NavButton color="inherit" component={Link} to="/invoice">
                Invoices
              </NavButton>

              <Tooltip title="Notifications" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  sx={{ mx: 1 }}
                >
                  <Badge badgeContent={4} color="secondary">
                    <Notifications />
                  </Badge>
                </IconButton>
              </Tooltip>

              <Tooltip title="Toggle dark mode" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  onClick={toggleDarkMode}
                  sx={{ mx: 1 }}
                >
                  {darkMode ? <Brightness7 /> : <Brightness4 />}
                </IconButton>
              </Tooltip>

              <IconButton
                size="large"
                edge="end"
                aria-label="account"
                onClick={handleProfileMenuOpen}
                color="inherit"
                sx={{ ml: 1 }}
              >
                <motion.div whileHover={{ scale: 1.1 }}>
                  <Avatar
                    alt="User"
                    src="/static/images/avatar/1.jpg"
                    sx={{
                      transition: 'all 0.3s ease',
                      boxShadow: theme.shadows[4],
                      '&:hover': {
                        transform: 'translateY(-4px) scale(1.05)',
                        boxShadow: theme.shadows[10],
                      },
                    }}
                  />
                </motion.div>
              </IconButton>
            </Box>
          </Toolbar>
        </GlassAppBar>
      </motion.div>

      {/* Profile menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          elevation: 8,
          sx: {
            borderRadius: '16px',
            minWidth: '220px',
            overflow: 'visible',
            mt: 1.5,
            '&:before': {
              content: '""',
              display: 'block',
              position: 'absolute',
              top: 0,
              right: 14,
              width: 10,
              height: 10,
              bgcolor: 'background.paper',
              transform: 'translateY(-50%) rotate(45deg)',
              zIndex: 0,
            },
          },
        }}
      >
        <MenuItem 
          onClick={handleMenuClose} 
          component={Link} 
          to="/profile"
          sx={{
            '&:hover': {
              backgroundColor: alpha(theme.palette.primary.main, 0.1),
            },
          }}
        >
          <Avatar sx={{ mr: 2 }} />
          <Box>
            <Typography variant="subtitle1">Abhishek</Typography>
            <Typography variant="caption" color="text.secondary">
              Premium Member
            </Typography>
          </Box>
        </MenuItem>
        <Divider />
        <MenuItem onClick={toggleDarkMode}>
          {darkMode ? (
            <Brightness7 sx={{ mr: 2 }} fontSize="small" />
          ) : (
            <Brightness4 sx={{ mr: 2 }} fontSize="small" />
          )}
          {darkMode ? 'Light Mode' : 'Dark Mode'}
          <Switch checked={darkMode} onChange={toggleDarkMode} sx={{ ml: 'auto' }} />
        </MenuItem>
      </Menu>

      {/* Spacer for fixed navbar */}
      <Toolbar sx={{ height: scrolled ? '60px' : '80px' }} />

      {/* Scroll to top button */}
      <AnimatePresence>
        {scrolled && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            style={{
              position: 'fixed',
              bottom: '32px',
              right: '32px',
              zIndex: theme.zIndex.speedDial,
            }}
          >
            <Tooltip title="Scroll to top" arrow>
              <IconButton
                onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                sx={{
                  backgroundColor: theme.palette.primary.main,
                  color: theme.palette.primary.contrastText,
                  boxShadow: theme.shadows[10],
                  '&:hover': {
                    backgroundColor: theme.palette.primary.dark,
                  },
                }}
                size="large"
              >
                <KeyboardArrowUp />
              </IconButton>
            </Tooltip>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

function debounce(func, wait) {
  let timeout;
  return function(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

export default Navbar;
